import json, sys
from collections import Counter, defaultdict

def load(path):
    return json.load(open(path, encoding='utf-8'))

TYPE_TAGS = Counter()
DYNAMIC_REFS = Counter()
LOCAL_STORAGE_REFS = Counter()
ACTION_CMDS = Counter()
FUNC_CALLS = Counter()
COMPARISON_OPS = Counter()
MATH_OPS = Counter()
PRIMITIVE_VALUES = []

def walk(node, path=""):
    if isinstance(node, dict):
        keys = list(node.keys())
        for k in keys:
            v = node[k]
            if k in ("LOGIC","COMPARISON","MATH","FUNC","VAR","STORE","SUBCOMMANDS") or k.isupper():
                TYPE_TAGS[k] += 1
            if k == "DYNAMIC" and isinstance(v, list) and len(v) >= 1:
                # v[0] is namespace (settings/indicator name), v[1] is field expr
                ns = v[0]
                field = None
                try:
                    field = extract_primitive_string(v[1])
                except Exception:
                    field = None
                DYNAMIC_REFS[(ns, field)] += 1
            if k == "LOCAL_STORAGE" and isinstance(v, list):
                key_path = tuple(x for x in v[:-1] if isinstance(x, str))
                LOCAL_STORAGE_REFS[key_path] += 1
            if k == "COMPARISON" and isinstance(v, dict):
                for op in v.keys():
                    COMPARISON_OPS[op] += 1
            if k == "MATH" and isinstance(v, dict):
                for op in v.keys():
                    MATH_OPS[op] += 1
            if k == "FUNC":
                FUNC_CALLS[json.dumps(v)[:80]] += 1
            if k in ("PLACE_ORDER","CANCEL_ORDER","MODIFY_ORDER","SEND_MESSAGE","SAVE_VAR","ORDER","MARKET_ORDER","LIMIT_ORDER"):
                ACTION_CMDS[k] += 1
            walk(v, path + "/" + k)
    elif isinstance(node, list):
        for item in node:
            walk(item, path + "[]")

def extract_primitive_string(node):
    # node like {"VAR": {"PRIMITIVE": {"STRING": "range_1h"}}}
    if isinstance(node, dict):
        if "VAR" in node:
            return extract_primitive_string(node["VAR"])
        if "PRIMITIVE" in node:
            p = node["PRIMITIVE"]
            if isinstance(p, dict):
                if "STRING" in p:
                    return p["STRING"]
                if "F64" in p:
                    return p["F64"]
        # fallback: recurse first value
        for v in node.values():
            r = extract_primitive_string(v)
            if r is not None:
                return r
    return None

if __name__ == '__main__':
    path = sys.argv[1]
    d = load(path)
    walk(d)
    print("=== TYPE_TAGS (structural keywords) ===")
    for k,c in TYPE_TAGS.most_common(60):
        print(f"{k}: {c}")
    print("\n=== DYNAMIC namespace/field refs (top 200) ===")
    for k,c in DYNAMIC_REFS.most_common(200):
        print(f"{k}: {c}")
    print("\n=== LOCAL_STORAGE keys ===")
    for k,c in LOCAL_STORAGE_REFS.most_common(100):
        print(f"{k}: {c}")
    print("\n=== COMPARISON ops ===")
    for k,c in COMPARISON_OPS.most_common(20):
        print(f"{k}: {c}")
    print("\n=== MATH ops ===")
    for k,c in MATH_OPS.most_common(20):
        print(f"{k}: {c}")
    print("\n=== ACTION cmds ===")
    for k,c in ACTION_CMDS.most_common(20):
        print(f"{k}: {c}")
    print("\n=== top-level blocks ===")
    blocks = d.get("blocks", [])
    print("num blocks:", len(blocks))
    for b in blocks:
        key = b.get("key")
        has_sensor = "trading_sensors" in b
        has_action = "trading_actions" in b
        sensor_type = list(b.get("trading_sensors",{}).keys()) if has_sensor else None
        action_type = list(b.get("trading_actions",{}).keys()) if has_action else None
        print(key, sensor_type, action_type, list(b.keys()))

